const root = $input.first().json.rss.channel;
const channel = Array.isArray(root) ? root[0] : root;
const rawItems = channel.item;
const items = Array.isArray(rawItems) ? rawItems : [rawItems];
const trendDate = new Date(Date.now() + 9 * 60 * 60 * 1000).toISOString().slice(0, 10); // KST date, not UTC

const pick = (obj, key) => {
  const v = obj?.[key];
  return Array.isArray(v) ? v[0] : v;
};

const results = items.slice(0, 20).map((item, idx) => ({
  json: {
    rank: idx + 1,
    keyword: pick(item, 'title') || '',
    approx_traffic: pick(item, 'ht:approx_traffic') || null,
    trend_link: pick(item, 'link') || '',
    region: 'KR',
    trend_date: trendDate,
    source: 'trend'
  }
}));

return results;

// NOTE: field names above (e.g. 'ht:approx_traffic') depend on how the
// XML node namespaces tags in your n8n version. Verify against a live run.

const COOLDOWN_DAYS = 14;
const cooldownMs = COOLDOWN_DAYS * 24 * 60 * 60 * 1000;
const now = Date.now();
const today = new Date(now + 9 * 60 * 60 * 1000).toISOString().slice(0, 10); // KST date, not UTC

const topKeywords = $('Extract Top 20').all().map(i => i.json); // ranked, index 0 = highest volume
const allRows = $input.all().map(i => i.json); // Get Recently Posted output (includes rows Insert Keywords History just wrote)

const recentlyPosted = new Set(
  allRows
    .filter(r => r.posted_at && (now - new Date(r.posted_at).getTime()) < cooldownMs)
    .map(r => r.keyword)
);

const candidate = topKeywords.find(k => !recentlyPosted.has(k.keyword));
if (!candidate) {
  return []; // nothing new this run -- everything downstream simply won't fire
}

const dbRow = allRows.find(r => r.keyword === candidate.keyword && r.trend_date === today && r.region === 'KR');
if (!dbRow) {
  // Should not happen since Insert Keywords History ran first, but bail safely if it does.
  return [];
}

return [{
  json: {
    id: dbRow.id,
    keyword: dbRow.keyword,
    approx_traffic: dbRow.approx_traffic,
    trend_link: dbRow.trend_link
  }
}];

// Loop entry point: reached either from Pick Next Keyword (attempt starts at 1)
// or from IF Approval Retry looping back (attempt already incremented). Normalizes
// the shape either way so Send Telegram / Wait / Evaluate can rely on a stable node name.
const input = $input.first().json;
return [{
  json: {
    id: input.id,
    keyword: input.keyword,
    approx_traffic: input.approx_traffic,
    trend_link: input.trend_link,
    attempt: input.attempt || 1
  }
}];

// $json here is either the Telegram webhook resume payload (button click) or,
// if Wait's time limit fired first, a passthrough of whatever fed the Wait node --
// so attempt/keyword data always comes from the named Keyword Approval Attempt node.
const attemptData = $('Keyword Approval Attempt').item.json;
const hasDecision = $json.query && typeof $json.query.decision !== 'undefined';

if (hasDecision) {
  return [{
    json: {
      ...attemptData,
      outcome: $json.query.decision === 'approve' ? 'proceed' : 'rejected'
    }
  }];
}

const MAX_ATTEMPTS = 5;
if (attemptData.attempt >= MAX_ATTEMPTS) {
  return [{ json: { ...attemptData, outcome: 'proceed', auto_approved: true } }];
}
return [{ json: { ...attemptData, attempt: attemptData.attempt + 1, outcome: 'retry' } }];

const message = $input.first().json.message;
const text = (message && message.text) || '';
const match = text.match(/^\/post\s+(.+)/i);
if (!match) {
  return []; // not a /post command -- ignore
}
const keyword = match[1].trim();
const today = new Date(Date.now() + 9 * 60 * 60 * 1000).toISOString().slice(0, 10); // KST date, not UTC
return [{
  json: {
    keyword,
    rank: null,
    approx_traffic: null,
    trend_link: null,
    region: 'KR',
    trend_date: today,
    source: 'manual'
  }
}];

const message = $input.first().json.message;
const text = (message && message.text) || '';
const match = text.match(/^(승인|거절)\s*[:\-]?\s*([\s\S]*)$/);
if (!match) {
  return []; // not an approval-style reply -- ignore (e.g. /post commands, unrelated chat)
}
const decision = match[1] === '승인' ? 'approve' : 'reject';
const comment = match[2].trim() || null;
return [{ json: { decision, comment } }];

const decision = $('Parse Approval Comment').item.json.decision;
const comment = $('Parse Approval Comment').item.json.comment;
const rows = $input.all().map(i => i.json);
const pending = rows.filter(r => r.pending_review_resume_url).sort((a, b) => b.id - a.id)[0];
if (!pending) {
  return []; // nothing currently waiting on a news-review approval -- ignore this reply
}
return [{ json: { decision, comment, resume_url: pending.pending_review_resume_url, id: pending.id } }];

// Single convergence point for Flow A (approved trend, arrives after a Wait node -- so $json/$input
// at this point would just be the Telegram resume payload, NOT the keyword data) and Flow B (manual
// /post, arrives directly with no Wait in between). Reference the real source explicitly by name.
let source;
try {
  source = $('Pick Next Keyword').item.json;
} catch (e) {
  source = $('Insert Manual Keyword').item.json;
}
return [{
  json: {
    id: source.id,
    keyword: source.keyword,
    trend_link: source.trend_link || null
  }
}];

const RECENCY_HOURS = 48;
const keywordCtx = $('Keyword Context').item.json;
const response = $input.first().json;
const articles = response.items || [];
const cutoff = Date.now() - RECENCY_HOURS * 3600 * 1000;

const recent = articles
  .filter(a => {
    const t = new Date(a.pubDate).getTime();
    return !isNaN(t) && t >= cutoff;
  })
  .map(a => ({
    keyword_id: keywordCtx.id,
    title: (a.title || '').replace(/<[^>]+>/g, ''),
    url: a.originallink || a.link,
    source: 'naver_news',
    published_at: a.pubDate
  }));

// Always return exactly ONE item (even when recent.length === 0) -- n8n skips
// downstream nodes entirely when an item count hits zero, which used to silently
// kill the 'no recent news' Telegram notification. IF News Found now reads
// count/articles directly off this single item instead of depending on
// Insert News/Aggregate News having actually run.
return [{ json: { keyword_id: keywordCtx.id, count: recent.length, articles: recent } }];

const keywordCtx = $('Keyword Context').item.json;
const agg = $input.first().json;
const titles = agg.title || [];
const urls = agg.url || [];
const newsLines = titles.map((t, i) => `${i + 1}. ${t}\n   ${urls[i] || ''}`).join('\n') || '(관련 뉴스 없음)';

return [{
  json: {
    id: keywordCtx.id,
    keyword: keywordCtx.keyword,
    trend_link: keywordCtx.trend_link,
    news_list: newsLines
  }
}];

// Loop entry point: reached either from Build News Summary (attempt starts at 1)
// or from IF News Retry looping back (attempt already incremented).
const input = $input.first().json;
return [{
  json: {
    id: input.id,
    keyword: input.keyword,
    trend_link: input.trend_link,
    news_list: input.news_list,
    attempt: input.attempt || 1
  }
}];

const attemptData = $('News Review Attempt').item.json;
const hasDecision = $json.query && typeof $json.query.decision !== 'undefined';

if (hasDecision) {
  return [{
    json: {
      ...attemptData,
      outcome: $json.query.decision === 'approve' ? 'proceed' : 'rejected',
      comment: $json.query.comment || null
    }
  }];
}

const MAX_ATTEMPTS = 5;
if (attemptData.attempt >= MAX_ATTEMPTS) {
  return [{ json: { ...attemptData, outcome: 'proceed', auto_approved: true, comment: null } }];
}
return [{ json: { ...attemptData, attempt: attemptData.attempt + 1, outcome: 'retry' } }];

