const response = $input.first().json;
const toolUse = (response.content || []).find(c => c.type === 'tool_use');
if (!toolUse) {
  throw new Error('Claude 응답에 tool_use가 없습니다: ' + JSON.stringify(response));
}
return [{ json: toolUse.input }];

const response = $input.all().map(i => i.json);
const targetName = $('Parse Claude Response').item.json.category;
const match = response.find(c => c.name === targetName);
return [{ json: { found: !!match, id: match ? match.id : null, name: targetName } }];

const claudeTags = $('Parse Claude Response').item.json.tags || [];
const existingTags = $input.all().map(i => i.json);
const existingByName = new Map(existingTags.map(t => [String(t.name).toLowerCase(), t.id]));
const resolvedIds = [];
const missingNames = [];
for (const name of claudeTags) {
  const id = existingByName.get(String(name).toLowerCase());
  if (id) resolvedIds.push(id);
  else missingNames.push(name);
}
if (missingNames.length === 0) {
  return [{ json: { needsCreate: false, resolvedIds } }];
}
return missingNames.map(name => ({ json: { needsCreate: true, name, resolvedIds } }));

const createdIds = ($input.first().json.id || []);
const resolvedIds = $('Resolve Tag IDs').first().json.resolvedIds || [];
return [{ json: { tag_ids: [...resolvedIds, ...createdIds] } }];
